    { id = "a19rr-001", ["do"] = "goto", at = {1433, 9.7, 70.9, "Tres Caminos (Marcy Baker)"}, radius = 20, text = "Desde Ventormenta, cruza Elwynn hacia el este hasta Tres Caminos, a la entrada de Crestagrana.", status = "unverified" },
    { id = "a19rr-002", ["do"] = "note", npc = 256390, at = {1433, 9.7, 70.9}, optional = true, text = "Favor de mercader: entrega a Marcy Baker las cajas de suministros y órdenes de trabajo que lleves.", tip = "Haz antes madejas: 20 madejas de lino dan 10 de Favor; 40 de lino suelto, solo 5. 20 de Polvo extraño dan 5. Las cajas caen de enemigos y en mazmorras.", status = "unverified" },
    { id = "a19rr-003", ["do"] = "note", npc = 256390, at = {1433, 9.7, 70.9}, optional = true, text = "Si te dieron una etiqueta de envío en la primera entrega, haz clic derecho en ella y entrégasela a Marcy: 50 de Favor.", tip = "Es la misión Shipping Label (98247). En QuestieDB figura con nivel 60 porque escala; se puede hacer desde el 10.", status = "unverified" },
    { id = "a19rr-004", ["do"] = "note", npc = 256735, at = {1433, 9.3, 71.5}, ["if"] = { prof = {"tailoring"} }, optional = true, text = "Con Favor, compra patrones a Mivin Shadowweave: Sombras para el brujo, Silky para el mago.", status = "unverified" },
    { id = "a19rr-005", ["do"] = "accept", quest = 244, npc = 464, at = {1433, 10.4, 71.3}, text = "Coge con el Guardia Parker, que patrulla el camino, el aviso para el Ayudante Feldon.", tip = "Imprescindible: sin entregar esta misión, Feldon no te ofrece la de los cazadores furtivos. Parker patrulla el camino entre Tres Caminos y el puente de Villa del Lago; si no está en el punto, recorre el camino.", status = "unverified" },
    { id = "a19rr-006", ["do"] = "getfp", npc = 931, at = {1433, 25.5, 59.4}, node = "5", text = "Sigue el camino al este hasta Villa del Lago. Coge la ruta de vuelo con Ariena Stormfeather, al sur del puente.", status = "unverified" },
    { id = "a19rr-007", ["do"] = "turnin", quest = 244, npc = 1070, at = {1433, 25.6, 60.0}, text = "Entrega al Ayudante Feldon, junto al maestro de vuelo.", status = "unverified" },
    { id = "a19rr-008", ["do"] = "accept", quest = 246, npc = 1070, at = {1433, 25.6, 60.0}, text = "Coge la misión de gnolls de Feldon (chuchos y cazadores furtivos).", tip = "Solo aparece si antes has entregado el aviso del Guardia Parker (paso anterior). Si Feldon no te la da, vuelve a buscar a Parker en el camino del oeste.", status = "unverified" },
    { id = "a19rr-009", ["do"] = "accept", quest = 98407, npc = 1070, at = {1433, 25.6, 60.0}, text = "Coge también la de los collares de los trituradores.", status = "unverified" },
    { id = "a19rr-010", ["do"] = "sethearth", npc = 6727, at = {1433, 21.9, 44.8}, zone = 1433, text = "Cruza el puente y pon la piedra de hogar en la posada de Villa del Lago.", status = "unverified" },
    { id = "a19rr-011", ["do"] = "turnin", quest = 65, npc = 266, at = {1433, 21.4, 45.4}, text = "Entrega La Hermandad Defias a Wiley el Negro, en la posada.", status = "unverified" },
    { id = "a19rr-012", ["do"] = "accept", quest = 132, npc = 266, at = {1433, 21.4, 45.4}, text = "Coge la nota de Wiley para Gryan Stoutmantle. La entregarás al volver a Poniente.", status = "unverified" },
    { id = "a19rr-013", ["do"] = "accept", quest = 127, npc = 381, at = {1433, 22.6, 47.4}, text = "En el muelle, coge las dos misiones de múrlocs del Jefe de muelle Baren (pescado).", status = "unverified" },
    { id = "a19rr-014", ["do"] = "accept", quest = 150, npc = 381, at = {1433, 22.6, 47.4}, text = "Coge también la de las aletas de múrloc.", status = "unverified" },
    { id = "a19rr-015", ["do"] = "accept", quest = 92, npc = 343, at = {1433, 17.6, 43.8}, text = "Coge el estofado de Crestagrana con la Chef Breanna.", status = "unverified" },
    { id = "a19rr-016", ["do"] = "accept", quest = 125, npc = 341, at = {1433, 27.1, 48.6}, text = "Coge con el Capataz Oslow la misión de su caja de herramientas.", status = "unverified" },
    { id = "a19rr-017", ["do"] = "accept", quest = 20, npc = 382, at = {1433, 28.4, 49.0}, text = "Coge con el Mariscal Marris la de las hachas de Roca Negra.", status = "unverified" },
