    { id = "a19rr-027", ["do"] = "complete", quest = 98407, at = {1433, 10.9, 66.3}, text = "Al suroeste, cerca de Tres Caminos, consigue 5 collares de los trituradores de Crestagrana.", status = "unverified" },
