    { id = "a34-desolace-008", ["do"] = "getfp", npc = 6706, at = {1443, 64.66, 10.54}, node = "Nijel's Point", text = "Coge la ruta de vuelo de Punta de Nijel con Baritanas Skyriver.", status = "unverified" },
    { id = "a34-desolace-009", ["do"] = "sethearth", npc = 11103, at = {1443, 66.27, 6.55}, text = "Pon la piedra de hogar en la posada de Punta de Nijel.", tip = "Volverás aquí varias veces a entregar.", status = "unverified" },
    { id = "a34-desolace-010", ["do"] = "turnin", quest = 1453, npc = 5638, at = {1443, 66.2, 9.63}, text = "Entrega la misión de los Reclamadores a Kreldig Ungor.", status = "unverified" },
    { id = "a34-desolace-011", ["do"] = "accept", quest = 1458, npc = 5638, at = {1443, 66.2, 9.63}, text = "Coge el primer encargo de reactivos de Kreldig.", status = "unverified" },
    { id = "a34-desolace-012", ["do"] = "accept", quest = 1387, npc = 5752, at = {1443, 66.74, 10.87}, text = "Coge la recompensa por orejas de centauro del cabo Melkins.", tip = "Sirve cualquier centauro: la completarás sin buscarla.", status = "unverified" },
    { id = "a34-desolace-013", ["do"] = "accept", quest = 1382, npc = 5396, at = {1443, 66.66, 10.93}, text = "Coge la alianza con los centauros del capitán Pentigast.", tip = "Elige Gelkis (Uthek). No cojas la de los Magram (Brutal Politics): los dos clanes se excluyen.", status = "unverified" },
    { id = "a34-desolace-014", ["do"] = "accept", quest = 93224, npc = 5396, at = {1443, 66.66, 10.93}, text = "Coge también los tótems tallados de centauro de Pentigast (nueva de Forever).", status = "unverified" },
    { id = "a34-desolace-015", ["do"] = "accept", quest = 261, npc = 1182, at = {1443, 66.52, 7.91}, text = "Coge la Senda Escarlata del hermano Anton (pide nivel 34).", tip = "Los 30 devastadores no muertos están en el Valle de los Huesos: los harás al 38.", status = "unverified" },
    { id = "a34-desolace-016", ["do"] = "complete", quest = 1458, at = {1443, 75.7, 19.3}, text = "Mata sátiros Hatefury al este hasta tener garras y cuernos.", status = "unverified" },
    { id = "a34-desolace-017", ["do"] = "turnin", quest = 1458, npc = 5638, at = {1443, 66.2, 9.63}, text = "Entrega los reactivos a Kreldig.", status = "unverified" },
    { id = "a34-desolace-018", ["do"] = "accept", quest = 1459, npc = 5638, at = {1443, 66.2, 9.63}, text = "Coge el segundo encargo: veneno de escórpido y piel de kodo vieja.", tip = "Escórpidos y kodos están por toda la zona: complétala de paso.", status = "unverified" },
    { id = "a34-desolace-019", ["do"] = "accept", quest = 5741, npc = 11863, at = {1443, 38.88, 27.16}, text = "Ve al oeste y coge el cetro de luz de Azore Aldamort, en su torre.", status = "unverified" },
    { id = "a34-desolace-020", ["do"] = "complete", quest = 5741, at = {1443, 55.2, 30.1}, text = "Recupera el cetro en lo alto de la torre de la Fortaleza Hacha de Trueno.", tip = "Lo lleva un vigía en lo alto; los orcos Filo Ardiente van en grupos de dos.", status = "unverified" },
    { id = "a34-desolace-021", ["do"] = "turnin", quest = 5741, npc = 11863, at = {1443, 38.88, 27.16}, text = "Vuelve con Azore y entrega el cetro.", tip = "El Libro de los Ancianos sigue en las islas naga del norte (élites): sáltatelo.", status = "unverified" },
    { id = "a34-desolace-022", ["do"] = "turnin", quest = 1382, npc = 5397, at = {1443, 36.22, 79.25}, text = "Baja hacia el sur por el oeste de la zona hasta Uthek el Sabio y entrega la alianza.", status = "unverified" },
    { id = "a34-desolace-023", ["do"] = "accept", quest = 1384, npc = 5397, at = {1443, 36.22, 79.25}, text = "Coge de Uthek el asalto a los Kolkar.", status = "unverified" },
    { id = "a34-desolace-024", ["do"] = "complete", quest = 1384, at = {1443, 71.5, 46.1}, text = "Consigue amuletos toscos de los centauros Kolkar, en su poblado del este.", tip = "Aquí sacas también las orejas y los tótems.", status = "unverified" },
    { id = "a34-desolace-025", ["do"] = "accept", quest = 5561, npc = 11596, at = {1443, 60.86, 61.86}, text = "Al sur, en el Cementerio de Kodos, coge la redada de kodos de Smeed Scrabblescrew.", status = "unverified" },
    { id = "a34-desolace-026", ["do"] = "complete", quest = 5561, at = {1443, 55, 60}, text = "Usa el control de kodos en los kodos ancianos y llévalos hasta Smeed.", status = "unverified" },
    { id = "a34-desolace-027", ["do"] = "turnin", quest = 5561, npc = 11596, at = {1443, 60.86, 61.86}, text = "Entrega la redada a Smeed.", status = "unverified" },
    { id = "a34-desolace-028", ["do"] = "turnin", quest = 1384, npc = 5397, at = {1443, 36.22, 79.25}, text = "Vuelve con Uthek y entrega los amuletos.", status = "unverified" },
    { id = "a34-desolace-029", ["do"] = "accept", quest = 1370, npc = 5397, at = {1443, 36.22, 79.25}, text = "Coge el robo de provisiones a los Magram.", status = "unverified" },
    { id = "a34-desolace-030", ["do"] = "complete", quest = 1370, at = {1443, 72.4, 77.3}, text = "Roba carne seca en el poblado Magram, al sureste.", tip = "Ahora los Magram son hostiles: tira de uno en uno, sus chamanes ponen tótems.", status = "unverified" },
    { id = "a34-desolace-031", ["do"] = "complete", quest = 93224, at = {1443, 72, 75}, text = "Termina orejas y tótems de centauro antes de volver.", status = "unverified" },
    { id = "a34-desolace-032", ["do"] = "turnin", quest = 1370, npc = 5397, at = {1443, 36.22, 79.25}, text = "Entrega las provisiones a Uthek.", tip = "Ongeku y los kanes siguientes son de nivel 37-42: déjalos, la cadena nueva del valle rinde más.", status = "unverified" },
    { id = "a34-desolace-033", ["do"] = "note", at = {1445, 66.2, 51.6, "Timothy Worthington (Theramore)"}, ["if"] = { prof = {"tailoring"} }, text = "Sastre con 200 y nivel 35: entrena Artesano con Timothy Worthington en Theramore (66.2, 51.6).", status = "unverified" },
    { id = "a34-desolace-034", ["do"] = "train", npc = 5497, spells = {3552}, at = {1453, 49.56, 85.8}, ["if"] = { class = {"MAGE"}, minlevel = 38 }, text = "Mago al 36-38: Teletransporte a Ventormenta, entrena con Jennea y vuelve con la piedra de hogar.", status = "unverified" },
  },
})

Senda.Guides:RegisterSection({
  id = "a38-valle-de-huesos",
  title = "Valle de los Huesos (Shen'dralas)",
  levels = {38, 40},
  map = 2652,
  summary = "Cadena nueva de Forever con los Gelkis en la entrada sur del Valle de los Huesos (mapa de Shen'dralas), más los devastadores de la Senda Escarlata. Al acabar, vuelve a Punta de Nijel.",
  steps = {
    { id = "a38-valle-de-huesos-001", ["do"] = "accept", quest = 93034, npc = 5397, at = {1443, 36.22, 79.25}, text = "Coge de Uthek el Sabio la misión del Valle de los Huesos.", status = "unverified" },
    { id = "a38-valle-de-huesos-002", ["do"] = "turnin", quest = 93034, npc = 253177, at = {2652, 21.2, 23.2}, text = "Ve al este hasta Nerlokh, en la entrada sur del Valle de los Huesos.", status = "unverified" },
    { id = "a38-valle-de-huesos-003", ["do"] = "accept", quest = 93035, npc = 253177, at = {2652, 21.2, 23.2}, text = "Coge de Nerlokh la caza de devastadores.", status = "unverified" },
    { id = "a38-valle-de-huesos-004", ["do"] = "accept", quest = 93041, npc = 253177, at = {2652, 21.2, 23.2}, text = "Coge de Nerlokh la misión de la verdad.", status = "unverified" },
