    { id = "a38-valle-de-huesos-006", ["do"] = "complete", quest = 93035, at = {1443, 62, 87}, text = "Mata devastadores no muertos en el valle: cuentan para Nerlokh y para la Senda Escarlata.", tip = "Te faltan 30 para el hermano Anton: termina las dos a la vez.", status = "unverified" },
