    { id = "a38-valle-de-huesos-009", ["do"] = "complete", quest = 93037, at = {2652, 39, 29.2}, text = "Consigue otra vestimenta nigromántica para Nerlokh.", status = "unverified" },
    { id = "a38-valle-de-huesos-010", ["do"] = "turnin", quest = 93035, npc = 253177, at = {2652, 21.2, 23.2}, text = "Vuelve con Nerlokh y entrega los devastadores.", status = "unverified" },
    { id = "a38-valle-de-huesos-011", ["do"] = "turnin", quest = 93037, npc = 253177, at = {2652, 21.2, 23.2}, text = "Entrega los proscritos a Nerlokh.", tip = "Si te ofrece más misiones del valle (cautivos, entierros), cógelas solo si eres 40 o más.", status = "unverified" },
    { id = "a38-valle-de-huesos-012", ["do"] = "turnin", quest = 93041, npc = 5397, at = {1443, 36.22, 79.25}, text = "Lleva la calavera y la vestimenta a Uthek.", status = "unverified" },
