    { id = "a38-valle-de-huesos-015", ["do"] = "accept", quest = 1052, npc = 1182, at = {1443, 66.52, 7.91}, optional = true, text = "Coge la carta de Anton para Costasur (Monasterio Escarlata).", tip = "Solo si harás el Monasterio.", status = "unverified" },
    { id = "a38-valle-de-huesos-016", ["do"] = "turnin", quest = 1387, npc = 5752, at = {1443, 66.74, 10.87}, text = "Entrega las orejas de centauro a Melkins.", status = "unverified" },
    { id = "a38-valle-de-huesos-017", ["do"] = "turnin", quest = 93224, npc = 5396, at = {1443, 66.66, 10.93}, text = "Entrega los tótems a Pentigast.", status = "unverified" },
    { id = "a38-valle-de-huesos-018", ["do"] = "turnin", quest = 1459, npc = 5638, at = {1443, 66.2, 9.63}, text = "Entrega el veneno y la piel a Kreldig.", tip = "Las siguientes de Kreldig mandan al pecio Karnitol: sáltalas.", status = "unverified" },
    { id = "a38-valle-de-huesos-019", ["do"] = "level", level = 40, text = "Deberías estar cerca del 40. Si no, repite centauros o devastadores.", status = "unverified" },
