    { id = "a44-badlands-003", ["do"] = "goto", at = {1418, 53.4, 43.4}, text = "Desde el fuerte, ve al noroeste hasta las Tierras Inhóspitas; busca el campamento enano del centro.", status = "unverified" },
    { id = "a44-badlands-004", ["do"] = "accept", quest = 719, npc = 2910, at = {1418, 53.42, 43.39}, text = "Coge la misión del pico del prospector Ryedol.", status = "unverified" },
