    { id = "a44-badlands-006", ["do"] = "accept", quest = 709, npc = 2785, at = {1418, 51.39, 76.87}, text = "Ve a la cabaña del sur, con Theldurin el Perdido, y coge la solución a la ruina.", status = "unverified" },
